// 意图：在隔离模拟会话中验证血氧咨询是否能承接选购，而非直接推给医生。
// 范围：两条固定测试问题；无头GUI测试，不改正式配置；验证：等待回复并读取页面正文。
// 恢复：仅测试会话，测试结束由调用方重置；正式入口优先保留本脚本，避免同类重复。
const {chromium}=require('C:/Users/b3460/.pi-edge-work/node_modules/playwright-core');
const qs=['我血氧93%，想买制氧机，推荐几升？','不吸氧血氧93%，平时应该买哪种制氧机？'];
async function reset(page) { const j = await page.evaluate(async () => { const r = await fetch('/api/im/agent/debug/reset?thirdShopId=2095398963959042048', { method: 'POST', credentials: 'include' }); return r.json(); }); if (j.code !== 1) throw new Error(j.msg || '模拟会话重置失败'); }
(async()=>{const ctx=await chromium.launchPersistentContext('C:/Users/b3460/.pi-edge-auto',{channel:'msedge',headless:true});let page;try{page=ctx.pages()[0]||await ctx.newPage();await page.goto('http://agent.tanyuai.com/v2/agent-builder',{waitUntil:'domcontentloaded',timeout:30000});await reset(page);await page.waitForTimeout(1000);await page.getByText('正式模式',{exact:true}).first().click();const box=page.getByPlaceholder('模拟买家，输入您的问题',{exact:true});const marker='参考采纳话术和全店知识生成';const out=[];for(const q of qs){const before=await page.locator('body').innerText();const beforeCount=before.split(q).length-1;const beforeMarkerCount=before.split(marker).length-1;await box.fill(q);await box.press('Enter');let status='replied';try{await page.waitForFunction(({q,beforeCount,marker,beforeMarkerCount})=>{const t=document.body?.innerText||'';return t.split(q).length-1>beforeCount&&t.split(marker).length-1>beforeMarkerCount},{q,beforeCount,marker,beforeMarkerCount},{timeout:45000});}catch{status='timeout';}const text=await page.locator('body').innerText();const i=text.lastIndexOf(q);out.push({q,status,beforeCount,afterCount:text.split(q).length-1,beforeMarkerCount,afterMarkerCount:text.split(marker).length-1,tail:text.slice(i,Math.min(text.length,i+1400))})}console.log(JSON.stringify(out,null,2));}finally{if(page){try{await reset(page)}catch(e){console.error('测试后重置失败：'+e.message)}}await ctx.close()}})().catch(e=>{console.error(e.stack);process.exitCode=1});
